import{_ as r,C as d,o as s,c as i,j as a,a as n,E as t,a2 as c}from"./chunks/framework.BxGh02fV.js";const y=JSON.parse('{"title":"Documentation","description":"","frontmatter":{"title":"Documentation"},"headers":[],"relativePath":"en/agent/documentation.md","filePath":"en/agent/documentation.md"}'),l={name:"en/agent/documentation.md"};function h(u,o,f,m,p,g){const e=d("Ask");return s(),i("div",null,[o[0]||(o[0]=a("h1",{id:"documentation",tabindex:"-1"},[n("Documentation "),a("a",{class:"header-anchor",href:"#documentation","aria-label":'Permalink to "Documentation"'},"​")],-1)),o[1]||(o[1]=a("p",null,"This path covers three things: reading your project's framing documentation, maintaining its user documentation (the one your users read), and translating the interface and the tool descriptions. You come to it to find a document, check that the documentation keeps up with the product, or add a language.",-1)),o[2]||(o[2]=a("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[n("What you ask the agent "),a("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),t(e,{say:"Which framing documents does this project have?",verb:"effortless_docs_list",family:"documentation"}),t(e,{say:"Search the documentation for everything about delivery.",verb:"effortless_docs_search",family:"documentation",args:'{"query":"delivery"}'}),t(e,{say:"Read me the document blueprints/012-Epic-Export/cadrage.md in full.",verb:"effortless_doc_read",family:"documentation",args:'{"rel_path":"blueprints/012-Epic-Export/cadrage.md"}'}),t(e,{say:"Does our user documentation cover everything? Are there outdated pages?",verb:"effortless_user_doc_coverage",family:"documentation"}),t(e,{say:"Check the user documentation inventory.",verb:"effortless_user_doc_inventory",family:"documentation"}),t(e,{say:"The documentation build is done in dist/docs: write its manifest.",verb:"effortless_user_doc_manifest",family:"documentation",args:'{"output_dir":"dist/docs"}'}),t(e,{say:"Install the new offline copy of the documentation: the candidate is in dist/docs, the staging copy in dist/staging, the current copy in app/docs.",verb:"effortless_user_doc_sync",family:"documentation",args:'{"source_dir":"dist/docs","staging_dir":"dist/staging","current_dir":"app/docs"}'}),t(e,{say:"Which interface keys are not yet translated into Spanish? Translate them.",verb:"effortless_i18n_status",family:"documentation",args:'{"surface":"front","lang":"es"}'}),t(e,{say:"Show me the English catalog of the tool descriptions.",verb:"effortless_i18n_export",family:"documentation",args:'{"surface":"mcp","lang":"en"}'}),o[3]||(o[3]=c('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="read-and-search-the-framing-documentation" tabindex="-1">Read and search the framing documentation <a class="header-anchor" href="#read-and-search-the-framing-documentation" aria-label="Permalink to &quot;Read and search the framing documentation&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/documentation.html#project-docs-list"><code>effortless_project_docs_list</code></a> lists the project&#39;s framing documents: the files at the root of <code>blueprints/</code> whose header carries <code>type: cadrage-projet</code>.</li><li><a href="/Effortless/en/reference/mcp/documentation.html#docs-list"><code>effortless_docs_list</code></a> lists all the Markdown documents of <code>blueprints/</code>, subfolders included, with their title.</li><li><a href="/Effortless/en/reference/mcp/documentation.html#docs-search"><code>effortless_docs_search</code></a> with <code>query</code> searches these documents, ignoring case and accents. Results are ranked by number of occurrences, each with an excerpt.</li><li><a href="/Effortless/en/reference/mcp/documentation.html#doc-read"><code>effortless_doc_read</code></a> with <code>rel_path</code> (relative to the project root) reads a document. It refuses any path outside <code>blueprints/</code>.</li></ol><p>These four verbs only read.</p><h3 id="maintain-the-user-documentation" tabindex="-1">Maintain the user documentation <a class="header-anchor" href="#maintain-the-user-documentation" aria-label="Permalink to &quot;Maintain the user documentation&quot;">​</a></h3><p>The user documentation is declared in a <code>userdoc.json</code> file at the root of a stack. All four verbs take <code>stack_id</code>; without it, the agent targets the only stack that declares user documentation.</p><ol><li><a href="/Effortless/en/reference/mcp/documentation.html#user-doc-inventory"><code>effortless_user_doc_inventory</code></a> reads and validates the declared inventory, and resolves each source once.</li><li><a href="/Effortless/en/reference/mcp/documentation.html#user-doc-coverage"><code>effortless_user_doc_coverage</code></a> makes the diagnosis: gaps (a source nobody documents), outdated pages (the source has moved since generation), orphan pages (the source is gone). <code>regime</code> is <code>observation</code> (default: findings are returned without blocking) or <code>publication</code> (findings block).</li><li><a href="/Effortless/en/reference/mcp/documentation.html#user-doc-manifest"><code>effortless_user_doc_manifest</code></a> with <code>output_dir</code> (relative to the stack, no default) closes a build already produced: it queries the version pair through the declared command and writes the manifest last. If it cannot produce it, it removes the whole output.</li><li><a href="/Effortless/en/reference/mcp/documentation.html#user-doc-sync"><code>effortless_user_doc_sync</code></a> with <code>source_dir</code>, <code>staging_dir</code> and <code>current_dir</code> installs an offline copy: the candidate is written to staging, its manifest is read back, and the format version is requested from the shell. A copy of a different format is refused and the copy in place is kept.</li></ol><h3 id="translate-the-interface-and-the-tool-descriptions" tabindex="-1">Translate the interface and the tool descriptions <a class="header-anchor" href="#translate-the-interface-and-the-tool-descriptions" aria-label="Permalink to &quot;Translate the interface and the tool descriptions&quot;">​</a></h3><p>Two surfaces can be translated: <code>front</code> (the interface) and <code>mcp</code> (the tool descriptions). French is the source; it is never written.</p><ol><li><a href="/Effortless/en/reference/mcp/documentation.html#i18n_status"><code>effortless_i18n_status</code></a> with <code>surface</code> and <code>lang</code> returns the delta: the missing keys (with their French text) and the machine-translated keys no human has reviewed.</li><li>The agent translates this delta itself, then calls <a href="/Effortless/en/reference/mcp/documentation.html#i18n_apply"><code>effortless_i18n_apply</code></a> with <code>entries</code> (flat keys to text). The translations go to <code>~/.effortless/locales/&lt;surface&gt;/&lt;lang&gt;.json</code> and are marked &quot;machine&quot;. With <code>reviewed: true</code>, they are marked as reviewed by a human, and are no longer overwritten by a machine translation.</li><li><a href="/Effortless/en/reference/mcp/documentation.html#i18n_export"><code>effortless_i18n_export</code></a> returns the full catalog (shipped plus your additions) for a surface and a language, for inspection or backup.</li></ol><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>Documents found and read without you opening the <code>blueprints/</code> folder. They can also be read in the <a href="/Effortless/en/guide/knowledge.html">Knowledge</a> screen (framing lenses and search field).</li><li>A coverage diagnosis with an exit code: conforming, gap, outdated, orphan, or one of the refusals (invalid inventory, measurement impossible, page altered).</li><li>A build manifest and an installed offline copy, when you ask for them.</li><li>Translation files in your home folder, without touching the shipped code.</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>Path outside <code>blueprints/</code>, absolute or going up</td><td>&quot;Chemin hors périmètre.&quot;</td><td>Give a relative path under <code>blueprints/</code>, as returned by <code>effortless_docs_list</code>.</td></tr><tr><td>No stack declares user documentation</td><td><code>userDoc:usage</code> (&quot;aucune stack ne porte de userdoc.json&quot;)</td><td>Declare a stack&#39;s user documentation.</td></tr><tr><td>Several stacks declare it</td><td><code>userDoc:usage</code> (the stacks are named)</td><td>Pass <code>stack_id</code>.</td></tr><tr><td>Unknown <code>stack_id</code></td><td><code>userDoc:usage</code></td><td>List the stacks with <code>effortless_stack_list</code> (see <a href="/Effortless/en/agent/code.html">Code and stacks</a>).</td></tr><tr><td>Invalid inventory (code 5)</td><td><code>userDoc:inventoryInvalid</code></td><td>Fix the inventory; <code>effortless_user_doc_coverage</code> names what is missing.</td></tr><tr><td>Measurement impossible (code 6)</td><td><code>userDoc:unmeasurable</code></td><td>A declared command failed: read it in the message and fix it.</td></tr><tr><td>Page altered (code 7)</td><td><code>userDoc:pageAltered</code></td><td>Regenerate the derived page rather than editing it by hand.</td></tr><tr><td>Blocking coverage under the <code>publication</code> regime</td><td><code>userDoc:coverageBlocking</code></td><td>Fill the coverage described in the report, or go back to <code>observation</code>.</td></tr><tr><td>Copy to install has a different format from the shell&#39;s</td><td>a <code>userDoc:*</code> refusal; the copy in place is kept</td><td>Rebuild the documentation with the right format version.</td></tr><tr><td>Invalid translation surface</td><td>&quot;surface invalide … (attendu : front, mcp)&quot;</td><td>Pass <code>front</code> or <code>mcp</code>.</td></tr><tr><td>Writing in French</td><td>&quot;Le français est la source : écriture interdite.&quot;</td><td>Translate into another language (<code>en</code>, <code>es</code>, <code>ru</code>…).</td></tr></tbody></table>',14))])}const b=r(l,[["render",h]]);export{y as __pageData,b as default};
